// Monta o texto do candidato a partir do payload enviado pelo backend Nima
const body = $input.first().json.body || $input.first().json;
const tutor = body.tutor || {};
const respostas = body.respostas || {};
let userText = `Candidato: ${tutor.nome || 'Não informado'} (${tutor.email || 'sem email'})\n\nRespostas do questionário:\n`;
for (const [pergunta, resposta] of Object.entries(respostas)) {
  userText += `- ${pergunta}: ${resposta ?? 'Não respondido'}\n`;
}
return [{ json: { userText } }];

// Extrai o texto do parecer e a Nota Final X/100 da resposta da OpenAI
const resp = $input.first().json;
const relatorio = resp?.choices?.[0]?.message?.content || '';
const m = relatorio.match(/Nota\s*Final\s*:?\s*(\d{1,3})\s*\/\s*100/i);
const score = m ? parseInt(m[1], 10) : null;
return [{ json: { relatorio, score } }];
